INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(17366, 'koKR', 'Intruzi wdarli się do fabryki! Natychmiast uruchomić awaryjny protokół obrony!', 'Intruzi wdarli się do fabryki! Natychmiast uruchomić awaryjny protokół obrony!', 0),
(17913, 'koKR', 'Chronić Mechanar za wszelką cenę!', '', 0),
(18662, 'koKR', 'Przy precyzyjnym kącie i prędkości...', '', 0),
(18716, 'koKR', 'Szukam kogoś do pracy zespołowej...', '', 0),
(18717, 'koKR', 'Czas uzupełnić siłę roboczą.', '', 0),
(18725, 'koKR', 'Wolę wszystkiego doglądać osobiście...', '', 0),
(19059, 'koKR', 'Czekałem na was!', '', 0),
(19952, 'koKR', 'Lepiej zmykajcie, póki możecie.', '', 0),
(19953, 'koKR', 'Nie mówcie, że nie ostrzegałem...', '', 0),
(19954, 'koKR', 'Do licha, ale jestem dobry!', '', 0),
(19955, 'koKR', 'Myślicie, że możecie mi coś zrobić, co? Myślicie, że się was boję?', '', 0),
(19956, 'koKR', 'No dalej, dajcie z siebie wszystko. Wytrzymam!', '', 0),
(19957, 'koKR', 'Łobuzy!', '', 0),
(19959, 'koKR', '', 'Niezbyt cenicie sobie życie, co?', 0),
(19961, 'koKR', '', 'I nie wracajcie!', 0),
(19962, 'koKR', '', 'Endala finel endal!', 0),
(19963, 'koKR', '', 'Myślicie, że wytrzymacie ten żar?', 0),
(19964, 'koKR', '', 'Anar\'endal dracon!', 0),
(19965, 'koKR', '', 'Nie jestem sama.', 0),
(19966, 'koKR', '', 'Anu... bala belore...alon.', 0),
(20029, 'koKR', 'Prymitywna technika, a jednak całkiem skuteczna.', '', 0),
(20030, 'koKR', 'Moje obliczenia nie...', '', 0),
(20031, 'koKR', 'Wynik z góry przesądzony.', '', 0),
(20032, 'koKR', 'Przetwarzanie będzie kontynuowane zgodnie z harmonogramem!', '', 0),
(20033, 'koKR', 'Zostało wam mniej więcej pięć sekund życia.', '', 0),
(20034, 'koKR', 'Przewiduję bolesną śmierć.', '', 0),
(20035, 'koKR', 'Wasza strategia była wadliwa.', '', 0),
(20036, 'koKR', 'Tak, jedyny logiczny wynik.', '', 0),
(20037, 'koKR', 'Dwa razy mierz, raz tnij.', '', 0),
(20038, 'koKR', 'Jeśli moje dzielenie jest poprawne... powinniście być całkiem martwi.', '', 0),
(20039, 'koKR', 'Nieprzewidziana... okoliczność.', '', 0),
(20040, 'koKR', 'Teraz pracujesz dla mnie!', '', 0),
(20041, 'koKR', 'Mamy ścisły harmonogram. Nie będziecie przeszkadzać!', '', 0),
(20042, 'koKR', 'Drobna niedogodność.', '', 0),
(20043, 'koKR', 'Wygląda na to, że przegraliście.', '', 0),
(20044, 'koKR', 'Projekt będzie... kontynuowany.', '', 0),
(20710, 'koKR', '%s groźnie unosi młot...', '', 0);
